update public.products set description='Dried Ponmo is cow skin with much of its moisture removed, giving it a firm dry texture and longer keeping quality than wet prepared Ponmo; it is normally rehydrated and thoroughly cooked before use.', handling_protocols=array['Keep completely dry until ready to use.','Inspect before preparation and avoid pieces with visible mold or obvious spoilage.','Rehydrate with clean potable water and cook promptly after soaking.']::text[], storage_tips=array['Store in a clean airtight or moisture-resistant container in a cool, dry place.','For best household quality, use within about 1–2 months while completely dry.','After soaking, refrigerate and use within about 1–2 days.']::text[] where name='Dried Pomo' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
